{
  "description": "A single quadrupedal creature is shown in right-facing side profile against a plain light background, standing on all four limbs. The body is low and stout with a broad, flat head at the front and a thick fleshy tail extending off the left edge of the image. The dorsal side from the back of the head to the base of the tail is covered in overlapping large brown scales, while the ventral side, head, limbs and tail are pale pink with wrinkled, moist-looking skin. Six feathery pink external gills protrude from the sides of the head behind the eyes, three per side. The head has large golden eyes with dark pupils, small nostrils at the tip of a blunt snout, and dark mottled speckling on the crown. The four limbs are thick and end in five-toed feet with small claws.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flat and blunt-snouted with moist pinkish-brown skin, large golden eyes with black pupils on the sides, small round nostrils at the snout tip, and a slightly upturned mouth; dark speckled pigmentation on the crown",
      "where": "at the front right of the body, facing right"
    },
    {
      "part": "gills",
      "looks_like": "six feathery, pink, stalk-like external gills with fine filamentous branches along each stalk, three on each side of the head",
      "where": "protruding laterally from just behind the head where neck would be, three on the left side visible in profile and three on the right side visible above the head"
    },
    {
      "part": "scales",
      "looks_like": "large, overlapping, rounded keratinous scales in shades of brown and tan with darker edges, arranged in diagonal rows like armor",
      "where": "covering the entire dorsal surface from the base of the gills over the back and sides down to the lower flank, from neck to base of tail"
    },
    {
      "part": "legs",
      "looks_like": "four thick, fleshy, wrinkled limbs with pale pink skin and visible folds at the joints",
      "where": "two forelegs under the chest and two hindlegs under the mid-body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad, five-toed feet with short blunt claws on each toe and wrinkled skin continuing from the legs",
      "where": "at the distal end of each of the four legs, splayed flat on the ground"
    },
    {
      "part": "tail",
      "looks_like": "thick, fleshy, pale pink with wrinkled skin and faint transverse folds, tapering slightly",
      "where": "extending to the left from the rear of the body, partially cropped by the image edge"
    },
    {
      "part": "markings",
      "looks_like": "irregular dark brown to black speckles and mottling on the dorsal skin of the head, and subtle transverse wrinkled bands on the pale ventral skin and limbs",
      "where": "speckles concentrated on the top and sides of the head; wrinkled bands on the belly, throat, and limbs"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
